'use strict';
(()=>{
 // 首次指引独立于总览，不在dashboard插入建账欢迎卡。
 const onboarding=$('onboardingPanel');onboarding.hidden=true;
 const guide=document.createElement('dialog');guide.id='firstRunGuide';guide.setAttribute('aria-labelledby','guideTitle');guide.innerHTML='<div class="guide-top"><span>家有数 · 新手指引</span><button class="outline" id="guideLater" type="button">稍后继续</button></div><ol id="guideSteps" class="guide-steps"></ol><p id="guideNumber" class="eyebrow"></p><h2 id="guideTitle"></h2><p id="guideDescription"></p><p id="guideProgress" class="muted"></p><div class="actions"><button class="solid" id="guideGo">前往填写</button><button class="outline" id="guideBack">上一步</button><button class="outline" id="guideNext">下一步</button></div><p id="guideError" role="status"></p>';document.body.append(guide);
 const continueGuide=document.createElement('button');continueGuide.id='continueGuide';continueGuide.className='outline guide-resume';continueGuide.textContent='继续新手指引';continueGuide.hidden=true;document.body.append(continueGuide);
 const help=document.createElement('article');help.className='panel';help.innerHTML='<h2>使用指引</h2><p>建立账户 → 填收入与支出 → 核对余额与估值 → 查看本月变化。</p><button class="outline" id="restartGuide">重新查看四步指引</button>';document.querySelector('[data-page="settings"]').append(help);
 let progress={step:1,completed:false},guideLoaded=false;
 const steps=[['建立账户','添加现金、银行卡、平台余额和投资账户，填写纳入账本当天的初始余额或市值。初始余额不算收入。','去建立账户'],['填写每月收入和支出','收入按成员、来源和到账账户保存；每人各填一个月支出净总额，家庭自动相加，没有支出明确填0。','去填本月收支'],['核对余额和持仓估值','选择余额截至日期，填写各账户实际余额或总市值。月中可盘点，月底再确认最后一天的数据。','去核对余额与估值'],['查看这个月的变化','月中点击临时关账看已录结果，仍可继续修改；月末核对齐全后再正式关账，锁定本月。','查看本月结果']];
 function drawGuide(){const [title,description,action]=steps[progress.step-1];$('guideTitle').textContent=title;$('guideDescription').textContent=description;$('guideNumber').textContent=`第 ${progress.step} 步 / 共 4 步`;$('guideGo').textContent=action;$('guideBack').disabled=progress.step===1;$('guideNext').disabled=progress.step===1&&!D.accounts.length;$('guideNext').textContent=progress.step===4?'完成指引':'下一步';$('guideProgress').textContent=progress.step===1?D.accounts.length?`已建立 ${D.accounts.length} 个账户，可以继续。`:'请先建立至少一个账户，再进入下一步。':'随时可返回修改；指引进度不会影响账本。';$('guideSteps').replaceChildren();steps.forEach(([name],i)=>{const li=document.createElement('li');li.textContent=(i+1)+'. '+name;li.className=i+1===progress.step?'active':'';$('guideSteps').append(li);});continueGuide.hidden=progress.completed;}
 async function persist(){try{await api('/api/onboarding',progress);$('guideError').textContent='';}catch(e){$('guideError').textContent=e.message;throw e;}}
 function showGuide(){drawGuide();if(!guide.open)guide.showModal();}
 $('guideLater').onclick=()=>guide.close();continueGuide.onclick=showGuide;
 $('guideNext').onclick=async()=>{if(progress.step===1&&!D.accounts.length)return;const old={...progress};if(progress.step===4)progress.completed=true;else progress.step++;try{await persist();drawGuide();if(progress.completed)guide.close();}catch{progress=old;}};
 $('guideBack').onclick=async()=>{if(progress.step>1){progress.step--;try{await persist();drawGuide();}catch{}}};
 $('restartGuide').onclick=async()=>{progress={step:1,completed:false};try{await persist();showGuide();}catch{}};
 $('guideGo').onclick=()=>{guide.close();location.hash=progress.step===1?'#assets':'#entry';FamilyMonth.showView?.(progress.step===3?'balances':progress.step===4?'result':'flows');requestAnimationFrame(()=>{const id=progress.step===1?'manageName':progress.step===2?'recordAmount':progress.step===3?'monthBalanceDate':'previewMonth';$(id)?.focus();if(progress.step===4)$('previewMonth').click();});};
 async function loadGuide(){if(!D.live||guideLoaded)return;guideLoaded=true;try{progress=await api('/api/onboarding');drawGuide();if(!progress.completed)showGuide();}catch{guideLoaded=false;}}

 // 月中临时结算只读预览；原有正式关账接口及历史保护保持独立。
 const previewButton=document.createElement('button');previewButton.id='previewMonth';previewButton.type='button';previewButton.className='solid';previewButton.textContent='临时关账 · 预览本月结果';$('finishMonth').before(previewButton);$('finishMonth').className='outline';$('finishMonth').textContent='正式确认关账';
 $('finishMonth').closest('article').querySelector('h2').textContent='本月结果与正式关账';
 const explanation=document.createElement('p');explanation.className='muted';explanation.textContent='月中可随时预览，截至所选日期的已录结果不会锁定账目。正式关账在月末核对齐全后进行；尚未满足条件时，按钮保持灰色。';previewButton.parentElement.before(explanation);
 const previewPanel=document.createElement('article');previewPanel.id='temporaryMonthResult';previewPanel.className='panel';previewPanel.hidden=true;previewPanel.innerHTML='<div class="panel-head"><div><h2 id="temporaryTitle">本月临时结果</h2><p id="temporaryDate"></p></div><span class="status-tag">预览 · 不改账</span></div><div id="temporaryMetrics" class="expense-kpis"></div><p id="temporaryCoverage" class="muted"></p><p id="temporaryNote" class="muted"></p>';$('viewMonthReport').closest('article').after(previewPanel);
 previewButton.onclick=async()=>{FamilyMonth.showView?.('result');previewButton.disabled=true;try{const r=await api('/api/periods/preview?month='+encodeURIComponent($('workflowMonth').value)+'&through='+encodeURIComponent($('monthBalanceDate').value));$('temporaryTitle').textContent=r.month+' 临时结果';$('temporaryDate').textContent='截至 '+r.asOf+' · 读取已保存资料';$('temporaryMetrics').replaceChildren();for(const [key,label]of [['incomeCents','已录家庭收入'],['expenseCents','已录家庭支出'],['netCents','已录收支结余'],['assetsCents','账面家庭资产'],['deltaCents','较期初参考资产变化']]){const a=document.createElement('article'),l=document.createElement('span'),v=document.createElement('strong');l.textContent=label;v.textContent=money(r.summary[key]);a.append(l,v);$('temporaryMetrics').append(a);}$('temporaryCoverage').textContent=`截至当日已核对 ${r.checks.filter(c=>c.done).length}/${r.checks.length} 个账户；支出截至 ${r.expenseThrough||'尚未填写'}。`;$('temporaryNote').textContent=r.note;previewPanel.hidden=false;window.FamilyMetricHelp?.apply();previewPanel.scrollIntoView({behavior:'smooth',block:'start'});$('finishMonthStatus').textContent='已生成临时结果，未改变账目的关账状态。';}catch(e){$('finishMonthStatus').textContent=e.message;}finally{previewButton.disabled=false;}};

 for(const id of ['workflowMonth','monthBalanceDate'])$(id).addEventListener('change',()=>{previewPanel.hidden=true;});document.addEventListener('family-ledger-ready',()=>{previewPanel.hidden=true;});
 const widgets=[];
 function makeChart(parent,id,title,grain,reportRange=false){const a=document.createElement('article');a.className='panel income-lines-panel';a.innerHTML=`<div class="panel-head"><div><h2>${title}</h2><p class="muted">成员收入与家庭合计 · 人民币</p></div></div><div class="line-chart-controls"></div><div class="line-legend"></div><div class="line-svg"></div><p class="muted line-note"></p><details><summary>查看图表数据</summary><div class="table-scroll"><table><thead></thead><tbody></tbody></table></div></details>`;a.id=id;parent.append(a);const item={a,id,grain,reportRange,hidden:new Set()};if(reportRange){for(const [value,label]of [['month','按月'],['year','按年']]){const b=document.createElement('button');b.className='outline';b.textContent=label;b.onclick=()=>{item.grain=value;drawIncome(item);};a.querySelector('.line-chart-controls').append(b);}}widgets.push(item);return item;}
 const overview=document.querySelector('[data-page="overview"]'),charts=document.createElement('div');charts.className='dashboard-income-grid';$('trend').after(charts);makeChart(charts,'dashboardMonthlyIncome','每月收入变化','month');makeChart(charts,'dashboardYearlyIncome','每年收入变化','year');
 const oldIncome=$('incomeTrend').closest('section');oldIncome.hidden=true;const reportCharts=document.createElement('div');oldIncome.after(reportCharts);makeChart(reportCharts,'reportIncomeLines','两个人与家庭的收入曲线','month',true);
 function drawIncome(item){
  if(!D.live)return;let start,end=D.today;if(item.reportRange){start=$('start').value;end=$('end').value;}else if(item.grain==='month'){const date=new Date(D.today+'T00:00:00Z');date.setUTCDate(1);date.setUTCMonth(date.getUTCMonth()-11);start=date.toISOString().slice(0,10);}else{start=(D.reportingIncomes()[0]?.date||D.today).slice(0,4)+'-01-01';}
  const members=[...new Set([...(D.memberProfiles||[]).filter(p=>p.active).map(p=>p.key),...D.reportingIncomes().filter(r=>r.date>=start&&r.date<=end).map(r=>r.member)])];const s=FamilyIncomeSeries.series(D.reportingIncomes(),members,{grain:item.grain,start,end,today:D.today}),legend=item.a.querySelector('.line-legend');legend.replaceChildren();const palette=['#28745c','#cc8751','#537fa7','#a15d8b','#778b3c'];
  s.lines.forEach((line,i)=>{const b=document.createElement('button');b.type='button';b.textContent=line.member==='家庭合计'?'家庭合计':memberName(line.member);b.style.borderColor=palette[i%palette.length];b.style.color=palette[i%palette.length];b.setAttribute('aria-pressed',String(!item.hidden.has(line.member)));b.onclick=()=>{item.hidden.has(line.member)?item.hidden.delete(line.member):item.hidden.add(line.member);drawIncome(item);};legend.append(b);});
  const all=s.lines.filter(l=>!item.hidden.has(l.member)).flatMap(l=>l.values.filter(v=>v!==null)),rawMax=Math.max(...all,100),scale=10**Math.floor(Math.log10(rawMax/5)),step=[1,2,2.5,5,10].find(n=>n>=rawMax/5/scale)*scale,ticks=Math.ceil(rawMax/step),max=step*ticks,w=Math.max(580,Math.round(item.a.querySelector('.line-svg').clientWidth||720)),h=280,left=62,right=30,top=26,bottom=45,x=i=>s.labels.length===1?w/2:left+i*(w-left-right)/Math.max(s.labels.length-1,1),y=v=>h-bottom-(v/max)*(h-top-bottom);let svg=`<rect width="${w}" height="${h}" fill="white"/><text x="${left}" y="12" fill="#718078" font-size="11">金额（元）</text>`;
  for(let i=0;i<=ticks;i++){const v=step*i,amount=v/100,label=amount>=10000?(amount/10000).toLocaleString('zh-CN',{maximumFractionDigits:1})+'万':amount.toLocaleString('zh-CN',{maximumFractionDigits:0});svg+=`<line x1="${left}" y1="${y(v)}" x2="${w-right}" y2="${y(v)}" stroke="#e3e9e3" stroke-dasharray="3 5"/><text x="${left-12}" y="${y(v)+4}" text-anchor="end" fill="#718078" font-size="12">${label}</text>`;}
  s.labels.forEach((label,i)=>{const skip=Math.max(1,Math.ceil(s.labels.length/Math.max(4,Math.floor(w/100))));if((i%skip===0&&i<=s.labels.length-1-skip)||i===s.labels.length-1)svg+=`<text x="${x(i)}" y="${h-13}" text-anchor="middle" fill="#718078" font-size="12">${label}${s.partial[i]?'*':''}</text>`;});
  s.lines.forEach((line,li)=>{if(item.hidden.has(line.member))return;const color=palette[li%palette.length];line.values.forEach((v,i)=>{if(v===null)return;if(i&&line.values[i-1]!==null)svg+=`<line x1="${x(i-1)}" y1="${y(line.values[i-1])}" x2="${x(i)}" y2="${y(v)}" stroke="${color}" stroke-width="2"/>`;svg+=`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="${color}"><title>${escapeHTML((line.member==='家庭合计'?'家庭合计':memberName(line.member))+' · '+s.labels[i]+' · '+money(v))}</title></circle>`;});});
  item.a.querySelector('.line-svg').innerHTML=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${item.grain==='month'?'月':'年'}收入曲线"><title>成员收入及家庭合计</title>${svg}</svg>`;
  item.a.querySelector('.line-note').textContent=(all.length?'':'尚无可展示的收入记录。')+(s.unallocated?'有 '+s.unallocated+' 条历史汇总无法完整放入本图的月份/年份，未拆分或分摊；请切换统计粒度或查看汇总表。 ':'')+'* 本期未结束，仅为已录收入；缺少成员资料的月份不画成0，家庭合计需各成员都有记录。年度按已录收入相加，缺失月份不自动补零。点击图例可隐藏曲线，手机图表可左右滑动，亦可展开数据表查看具体金额。';
  const head=item.a.querySelector('thead'),body=item.a.querySelector('tbody');head.replaceChildren();body.replaceChildren();const tr=document.createElement('tr');for(const label of ['期间',...s.lines.map(l=>l.member==='家庭合计'?l.member:memberName(l.member))]){const th=document.createElement('th');th.textContent=label;tr.append(th);}head.append(tr);s.labels.forEach((label,i)=>{const row=document.createElement('tr');for(const value of [label+(s.partial[i]?'（截至今日）':''),...s.lines.map(l=>l.values[i]===null?'未记录':money(l.values[i]))]){const td=document.createElement('td');td.textContent=value;row.append(td);}body.append(row);});
 }
 function renderDashboard(){onboarding.hidden=true;for(const item of widgets)drawIncome(item);if(guideLoaded)drawGuide();loadGuide();}
 let chartFrame;function resizeCharts(){cancelAnimationFrame(chartFrame);chartFrame=requestAnimationFrame(()=>{for(const item of widgets)if(item.a.getClientRects().length)drawIncome(item);});}
 window.FamilyDashboard={render:renderDashboard};document.addEventListener('family-ledger-ready',renderDashboard);document.addEventListener('family-app-ready',renderDashboard);window.addEventListener('hashchange',()=>{onboarding.hidden=true;resizeCharts();});window.addEventListener('resize',resizeCharts);if(D.live)renderDashboard();
})();
